"""Business rules for notes: validation, tags and partial updates. No HTTP, no SQL."""

from __future__ import annotations

import re
from typing import Any

from .repository import NoteRepository

MAX_TITLE = 120
MAX_BODY = 10_000
MAX_TAGS = 10
TAG_RE = re.compile(r"^[a-z0-9][a-z0-9:._-]{0,29}$")


class ValidationError(ValueError):
    """Input violates a business rule (HTTP 400)."""


class NotFound(LookupError):
    """The note does not exist (HTTP 404)."""


def _title(value: Any) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValidationError("title is required")
    value = value.strip()
    if len(value) > MAX_TITLE:
        raise ValidationError(f"title must be at most {MAX_TITLE} characters")
    return value


def _body(value: Any) -> str:
    if value is None:
        return ""
    if not isinstance(value, str):
        raise ValidationError("body must be a string")
    if len(value) > MAX_BODY:
        raise ValidationError(f"body must be at most {MAX_BODY} characters")
    return value


def normalize_tag(value: Any) -> str:
    if not isinstance(value, str):
        raise ValidationError("tags must be strings")
    tag = value.strip().lower()
    if not TAG_RE.match(tag):
        raise ValidationError(f"invalid tag {value!r}: use a-z, 0-9, ':', '.', '_', '-' (max 30)")
    return tag


def _tags(value: Any) -> list[str]:
    if value is None:
        return []
    if not isinstance(value, list):
        raise ValidationError("tags must be a list of strings")
    tags = sorted({normalize_tag(v) for v in value})
    if len(tags) > MAX_TAGS:
        raise ValidationError(f"at most {MAX_TAGS} tags per note")
    return tags


class NoteService:
    def __init__(self, repo: NoteRepository) -> None:
        self.repo = repo

    def create(self, data: dict[str, Any]) -> dict[str, Any]:
        return self.repo.create(_title(data.get("title")), _body(data.get("body")), _tags(data.get("tags")))

    def get(self, note_id: int) -> dict[str, Any]:
        note = self.repo.get(note_id)
        if note is None:
            raise NotFound(f"note {note_id} not found")
        return note

    def list(self, q: str | None = None, tag: str | None = None) -> list[dict[str, Any]]:
        q = q.strip() if q else None
        if q and len(q) > 100:
            raise ValidationError("search query must be at most 100 characters")
        return self.repo.list(q=q or None, tag=normalize_tag(tag) if tag else None)

    def update(self, note_id: int, data: dict[str, Any]) -> dict[str, Any]:
        current = self.get(note_id)
        if not {"title", "body", "tags"} & data.keys():
            raise ValidationError("provide title, body and/or tags")
        title = _title(data["title"]) if "title" in data else current["title"]
        body = _body(data["body"]) if "body" in data else current["body"]
        tags = _tags(data["tags"]) if "tags" in data else current["tags"]
        note = self.repo.update(note_id, title, body, tags)
        if note is None:
            raise NotFound(f"note {note_id} not found")
        return note

    def delete(self, note_id: int) -> None:
        if not self.repo.delete(note_id):
            raise NotFound(f"note {note_id} not found")

"""SQLite persistence for notes and tags. The only module that writes SQL."""

from __future__ import annotations

import sqlite3
import threading
from datetime import datetime, timezone
from typing import Any

SCHEMA = """
CREATE TABLE IF NOT EXISTS notes (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    title      TEXT    NOT NULL,
    body       TEXT    NOT NULL DEFAULT '',
    created_at TEXT    NOT NULL,
    updated_at TEXT    NOT NULL
);
CREATE TABLE IF NOT EXISTS note_tags (
    note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    tag     TEXT    NOT NULL,
    PRIMARY KEY (note_id, tag)
);
CREATE INDEX IF NOT EXISTS idx_note_tags_tag ON note_tags(tag);
"""


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds")


def _like_pattern(text: str) -> str:
    escaped = text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    return f"%{escaped}%"


class NoteRepository:
    def __init__(self, path: str = ":memory:") -> None:
        self._conn = sqlite3.connect(path, check_same_thread=False)
        self._conn.row_factory = sqlite3.Row
        self._lock = threading.Lock()
        with self._lock, self._conn:
            self._conn.execute("PRAGMA foreign_keys = ON")
            self._conn.executescript(SCHEMA)

    def _hydrate(self, rows: list[sqlite3.Row]) -> list[dict[str, Any]]:
        notes = [dict(r) for r in rows]
        if not notes:
            return notes
        ids = [n["id"] for n in notes]
        marks = ",".join("?" * len(ids))
        tags: dict[int, list[str]] = {i: [] for i in ids}
        for row in self._conn.execute(
            f"SELECT note_id, tag FROM note_tags WHERE note_id IN ({marks}) ORDER BY tag", ids
        ):
            tags[row["note_id"]].append(row["tag"])
        for note in notes:
            note["tags"] = tags[note["id"]]
        return notes

    def _replace_tags(self, note_id: int, tags: list[str]) -> None:
        self._conn.execute("DELETE FROM note_tags WHERE note_id = ?", (note_id,))
        self._conn.executemany(
            "INSERT INTO note_tags (note_id, tag) VALUES (?, ?)", [(note_id, t) for t in tags]
        )

    def _fetch(self, note_id: int) -> dict[str, Any] | None:
        rows = self._conn.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchall()
        notes = self._hydrate(rows)
        return notes[0] if notes else None

    def create(self, title: str, body: str, tags: list[str]) -> dict[str, Any]:
        now = _now()
        with self._lock, self._conn:
            cur = self._conn.execute(
                "INSERT INTO notes (title, body, created_at, updated_at) VALUES (?, ?, ?, ?)",
                (title, body, now, now),
            )
            self._replace_tags(cur.lastrowid, tags)
            return self._fetch(cur.lastrowid)

    def get(self, note_id: int) -> dict[str, Any] | None:
        with self._lock:
            return self._fetch(note_id)

    def list(self, q: str | None = None, tag: str | None = None) -> list[dict[str, Any]]:
        sql = "SELECT * FROM notes WHERE 1 = 1"
        params: list[Any] = []
        if q:
            sql += " AND (title LIKE ? ESCAPE '\\' COLLATE NOCASE OR body LIKE ? ESCAPE '\\' COLLATE NOCASE)"
            params += [_like_pattern(q)] * 2
        if tag:
            sql += " AND id IN (SELECT note_id FROM note_tags WHERE tag = ?)"
            params.append(tag)
        sql += " ORDER BY updated_at DESC, id DESC"
        with self._lock:
            return self._hydrate(self._conn.execute(sql, params).fetchall())

    def update(self, note_id: int, title: str, body: str, tags: list[str]) -> dict[str, Any] | None:
        with self._lock, self._conn:
            cur = self._conn.execute(
                "UPDATE notes SET title = ?, body = ?, updated_at = ? WHERE id = ?",
                (title, body, _now(), note_id),
            )
            if cur.rowcount == 0:
                return None
            self._replace_tags(note_id, tags)
            return self._fetch(note_id)

    def delete(self, note_id: int) -> bool:
        with self._lock, self._conn:
            cur = self._conn.execute("DELETE FROM notes WHERE id = ?", (note_id,))
        return cur.rowcount > 0

"""HTTP layer: routing and JSON translation only."""

from __future__ import annotations

import json
import mimetypes
import os
import re
from pathlib import Path
from urllib.parse import parse_qs, urlsplit
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any

from .repository import NoteRepository
from .service import NoteService, NotFound, ValidationError
from .releases import build_release_notes, to_markdown
from .tasks_source import load_tasks

NOTE_PATH = re.compile(r"^/api/notes/(\d+)$")
RELEASE_PATH = re.compile(r"^/api/releases/([^/]+)/notes$")
DASHBOARD_DIR = Path(__file__).resolve().parent.parent / "dashboard"


def make_handler(service: NoteService) -> type[BaseHTTPRequestHandler]:
    class Handler(BaseHTTPRequestHandler):
        server_version = "ShipyardNotes/1.0"

        def log_message(self, fmt: str, *args: Any) -> None:
            if os.environ.get("NOTES_API_LOG"):
                super().log_message(fmt, *args)

        def _send(self, status: int, payload: Any = None) -> None:
            body = b"" if payload is None else json.dumps(payload).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _static(self, path: str) -> None:
            rel = "index.html" if path in ("", "/") else path.lstrip("/")
            target = (DASHBOARD_DIR / rel).resolve()
            if DASHBOARD_DIR not in target.parents or not target.is_file():
                return self._send(HTTPStatus.NOT_FOUND, {"error": f"no file {path}"})
            data = target.read_bytes()
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", mimetypes.guess_type(target.name)[0] or "application/octet-stream")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _text(self, status: int, text: str, content_type: str) -> None:
            data = text.encode()
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _json_body(self) -> dict[str, Any]:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b"{}"
            try:
                data = json.loads(raw or b"{}")
            except json.JSONDecodeError as exc:
                raise ValidationError("request body must be valid JSON") from exc
            if not isinstance(data, dict):
                raise ValidationError("request body must be a JSON object")
            return data

        def _dispatch(self, method: str) -> None:
            url = urlsplit(self.path)
            path = url.path
            query = {k: v[0] for k, v in parse_qs(url.query).items()}
            try:
                if path == "/api/health" and method == "GET":
                    return self._send(HTTPStatus.OK, {"status": "ok"})
                if path == "/api/tasks" and method == "GET":
                    return self._send(HTTPStatus.OK, load_tasks())
                release = RELEASE_PATH.match(path)
                if release and method == "GET":
                    notes = build_release_notes(service, release.group(1))
                    if query.get("format") == "markdown":
                        return self._text(HTTPStatus.OK, to_markdown(notes), "text/markdown; charset=utf-8")
                    return self._send(HTTPStatus.OK, notes)
                if path == "/api/notes":
                    if method == "GET":
                        return self._send(HTTPStatus.OK, service.list(q=query.get("q"), tag=query.get("tag")))
                    if method == "POST":
                        return self._send(HTTPStatus.CREATED, service.create(self._json_body()))
                match = NOTE_PATH.match(path)
                if match:
                    note_id = int(match.group(1))
                    if method == "GET":
                        return self._send(HTTPStatus.OK, service.get(note_id))
                    if method == "PATCH":
                        return self._send(HTTPStatus.OK, service.update(note_id, self._json_body()))
                    if method == "DELETE":
                        service.delete(note_id)
                        return self._send(HTTPStatus.NO_CONTENT)
                if method == "GET" and not path.startswith("/api/"):
                    return self._static(path)
                self._send(HTTPStatus.NOT_FOUND, {"error": f"no route for {method} {path}"})
            except ValidationError as exc:
                self._send(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            except NotFound as exc:
                self._send(HTTPStatus.NOT_FOUND, {"error": str(exc)})
            except Exception as exc:  # noqa: BLE001
                self._send(HTTPStatus.INTERNAL_SERVER_ERROR, {"error": repr(exc)})

        def do_GET(self) -> None:
            self._dispatch("GET")

        def do_POST(self) -> None:
            self._dispatch("POST")

        def do_PATCH(self) -> None:
            self._dispatch("PATCH")

        def do_DELETE(self) -> None:
            self._dispatch("DELETE")

    return Handler


def create_server(host: str = "0.0.0.0", port: int = 8000, db_path: str = "notes.db") -> ThreadingHTTPServer:
    service = NoteService(NoteRepository(db_path))
    return ThreadingHTTPServer((host, port), make_handler(service))


def main() -> None:
    port = int(os.environ.get("PORT", "8000"))
    server = create_server(port=port, db_path=os.environ.get("NOTES_DB", "notes.db"))
    print(f"Shipyard dashboard on http://localhost:{port}/  (API under /api/)")
    server.serve_forever()


if __name__ == "__main__":
    main()

