18	export function computeKpis(tasks, notes, today = todayIso()) {
19	  return {
20	    open: tasks.filter((t) => t.status !== "done").length,
21	    done: tasks.filter((t) => t.status === "done").length,
22	    overdue: tasks.filter((t) => isOverdue(t, today)).length,
23	    notes: notes.length,
24	  };
